// A graph under construction. Its builders (`matmul`, `conv2d`, …) are the op
// table's (`table.rs`); these rows are its lifecycle.
@[heap]
pub struct Graph {
mut:
	h voidptr
}

// close frees the handle now (V's GC runs no destructors).
pub fn (mut self Graph) close() {
	if self.h != unsafe { nil } {
		C.rlx_graph_free(self.h)
		self.h = unsafe { nil }
	}
}

fn adopt_graph(h voidptr) !&Graph {
	if h == unsafe { nil } {
		return RlxError{
			kind: 'runtime'
			message: 'rlx returned NULL'
		}
	}
	return &Graph{
		h: h
	}
}

// A graph split into self-contained parts that run in order: part i reads
// its `imports` from earlier parts' `exports` of the same name.
@[heap]
pub struct Partition {
mut:
	h voidptr
