// close frees the handle now (V's GC runs no destructors).
pub fn (mut self Partition) close() {
	if self.h != unsafe { nil } {
		C.rlx_partition_free(self.h)
		self.h = unsafe { nil }
	}
}

fn adopt_partition(h voidptr) !&Partition {
	if h == unsafe { nil } {
		return RlxError{
			kind: 'runtime'
			message: 'rlx returned NULL'
		}
	}
	return &Partition{
		h: h
	}
}

